#include "plugin_contract.hpp"
#include <QJsonArray>
#include <QJsonDocument>
#include <QRegularExpression>
namespace PluginContract{namespace{bool fail(QString*e,const QString&s){if(e)*e=s;return false;}bool idOk(const QString&s){static QRegularExpression r("^[A-Za-z0-9][A-Za-z0-9._-]{0,47}$");return r.match(s).hasMatch();}const QStringList events{"danmaku","gift","superchat","guard_buy"};}
bool validDescriptor(const Descriptor&d,QString*e){if(!idOk(d.id))return fail(e,"invalid_plugin_id");if(d.version.trimmed().isEmpty()||d.version.size()>64)return fail(e,"invalid_plugin_version");if(d.apiVersion!=ApiVersion)return fail(e,"unsupported_api_version");if(d.subscriptions.isEmpty()||d.subscriptions.size()>16)return fail(e,"invalid_subscriptions");for(const auto&s:d.subscriptions)if(!events.contains(s))return fail(e,"unknown_event");for(const auto&c:d.requestedCapabilities)if(c!="send_danmaku")return fail(e,"unknown_capability");return true;}
bool validateEvent(const QByteArray&b,QJsonObject*out,QString*e){if(b.isEmpty()||b.size()>MaxEventBytes)return fail(e,"event_size_limit");QJsonParseError p{};auto d=QJsonDocument::fromJson(b,&p);if(p.error!=QJsonParseError::NoError||!d.isObject())return fail(e,"invalid_event_json");auto o=d.object();if(o.value("api_version").toInt(-1)!=ApiVersion)return fail(e,"unsupported_api_version");if(!events.contains(o.value("type").toString()))return fail(e,"unknown_event");if(out)*out=o;return true;}
bool validateActions(const QByteArray&b,QList<ActionRequest>*out,QString*e){if(b.isEmpty()||b.size()>MaxActionBytes)return fail(e,"action_size_limit");QJsonParseError p{};auto d=QJsonDocument::fromJson(b,&p);if(p.error!=QJsonParseError::NoError||!d.isObject())return fail(e,"invalid_action_json");auto root=d.object();if(root.value("api_version").toInt(-1)!=ApiVersion)return fail(e,"unsupported_api_version");auto v=root.value("actions");if(!v.isArray()||v.toArray().size()>MaxActionsPerCall)return fail(e,"action_count_limit");QList<ActionRequest> result;for(const auto&item:v.toArray()){if(!item.isObject())return fail(e,"invalid_action");auto a=item.toObject();if(a.value("type").toString()!="send_danmaku")return fail(e,"unknown_action");auto t=a.value("text").toString();if(t.trimmed().isEmpty()||t.size()>180)return fail(e,"invalid_action_text");result.append({"send_danmaku",t});}if(out)*out=result;return true;}
}